{"path": "app/sudoku_solver.py", "content": "#!/usr/bin/env python3
"""
数独求解器 - 使用回溯算法
"""

def is_valid(board, row, col, num):
    """
    检查在 board[row][col] 位置放置数字 num 是否有效

    规则：
    - 每行必须包含 1-9 的数字，不能重复
    - 每列必须包含 1-9 的数字，不能重复
    - 每个 3x3 宫格必须包含 1-9 的数字，不能重复
    """
    # 检查行
    if any(board[row][col] == num and board[row][col] != 0):
        # 这里应该是检查同一行是否有相同的数
        for c in range(9):
            if board[row][c] == num and c != col:
                return False

    # 检查列
    for r in range(9):
        if board[r][col] == num and r != row:
            return False

    # 检查 3x3 宫格
    start_row = row // 3 * 3
    start_col = col // 3 * 3
    for r in range(start_row, start_row + 3):
        for c in range(start_col, start_col + 3):
            if board[r][c] == num and (r != row or c != col):
                return False

    return True


def find_empty(board):
    """
    查找下一个空白位置
    返回 (row, col) 元组，如果没有空白位置则返回 None
    """
    for r in range(9):
        for c in range(9):
            if board[r][c] == 0:
                return (r, c)
    return None


def solve_sudoku(board):
    """
    使用递归回溯算法求解数独
    返回 True 如果求解成功，否则返回 False
    """
    root = find_empty(board)

    if root is None:
        # 所有格子都已填充
        return True

    row, col = root

    for num in range(1, 10):
        if is_valid(board, row, col, num):
            board[row][col] = num
            if solve_sudoku(board):
                return True
            board[row][col] = 0  # 回溯，撤销选择

    return False


def read_puzzle(filepath):
    """
    读取数独谜题文件，返回 9x9 的二维数组
    """
    board = []
    with open(filepath, 'r', encoding='utf-8') as f:
        for line in f:
            line = line.strip()
            row = []
            for char in line:
                if char.isdigit():
                    row.append(int(char))
                else:
                    row.append(0)
            board.append(row)
    return board


def write_solution(board, filepath):
    """
    将求解结果写入文件
    格式为 9 行，每行 9 个连续数字（无空格）
    """
    with open(filepath, 'w', encoding='utf-8') as f:
        for row in board:
            f.write(''.join(str(num) for num in row) + '\n')


def main():
    """
    主函数
    """
    puzzle_file = 'app/puzzle.txt'
    solution_file = 'app/solution.txt'

    try:
        print("读取数独谜题...")
        board = read_puzzle(puzzle_file)

        if not solve_sudoku(board):
            print("错误：数独无解")
            return 1

        print("数独求解完成！")
        write_solution(board, solution_file)
        print("解答已写入：" + solution_file)

        return 0
    except FileNotFoundError as e:
        print("错误：文件未找到 - " + str(e))
        return 1
    except Exception as e:
        print("错误：" + str(e))
        return 1


if __name__ == "__main__":
    exit(main())
